import { CSSProperties } from 'react';

import styled from '@emotion/styled';

import { pillarStyles } from '../../constants';

type Variant = string;

const variantStyles: Record<Variant, CSSProperties> = {
  default: { backgroundColor: '#0000000a' },
  primary: { backgroundColor: '#fdd349' },
  innovation: { backgroundColor: pillarStyles.innovation.background },
  category: { backgroundColor: pillarStyles.category.background },
  consumer: { backgroundColor: pillarStyles.consumer.background },
  'portfolio-brand': {
    backgroundColor: pillarStyles['portfolio-brand'].background,
  },
  'connection-creativity': {
    backgroundColor: pillarStyles['connection-creativity'].background,
  },
  'trade-execution': {
    backgroundColor: pillarStyles['trade-execution'].background,
  },
  'value-creation': {
    backgroundColor: pillarStyles['value-creation'].background,
  },
};

export const StyledCardsContainer = styled.div<{ variant?: Variant }>(
  {
    display: 'flex',
    flexDirection: 'column',
    width: '100%',
    height: 'max-content',
    gap: '8px',
    borderRadius: '24px',
    padding: '24px',
  },
  (props) => ({
    ...(variantStyles[props.variant || 'default'] as CSSProperties),
  }),
);

export const StyledWrapper = styled.div({
  display: 'flex',
  flexDirection: 'row',
  gap: '16px',
});

export const StyledCardsContainerTitle = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  gap: '8px',
});

export const StyledCardsContainerTitleText = styled.h2<{
  titleSize: 'xl' | 'lg';
}>(
  {
    fontFamily: 'Barlow',
    fontWeight: '600',
    fontStyle: 'SemiBold',
    lineHeight: '120%',
    letterSpacing: '0%',
    color: '#0D0D0C',
    margin: '0',
  },
  (props) => ({
    fontSize: props.titleSize === 'xl' ? '40px' : '24px',
  }),
);

export const StyledCardsContainerSubtitle = styled.p({
  fontFamily: 'Work Sans',
  fontWeight: '400',
  fontStyle: 'Regular',
  fontSize: '16px',
  lineHeight: '140%',
  letterSpacing: '0%',
  color: '#0D0D0C',
  margin: '0',
  paddingBottom: '16px',
});

export const StyledIcon = styled.img<{
  titleSize: string;
}>(
  {
    width: '24px',
    height: '24px',
  },
  (props) => ({
    width: props.titleSize === 'xl' ? '33px' : '24px',
    height: props.titleSize === 'xl' ? '33px' : '24px',
  }),
);
